use crate::{commands,config::AppState};
use tauri::{menu::{Menu,MenuItem,PredefinedMenuItem},tray::{MouseButton,TrayIconBuilder,TrayIconEvent},AppHandle,Manager};
pub fn setup(app:&AppHandle)->tauri::Result<()>{let toggle=MenuItem::with_id(app,"show-hide","Mostrar / ocultar",true,None::<&str>)?;let reload=MenuItem::with_id(app,"reload","Recarregar página",true,None::<&str>)?;let settings=MenuItem::with_id(app,"settings","Configurações",true,None::<&str>)?;let sep=PredefinedMenuItem::separator(app)?;let state=app.state::<AppState>();let label=state.config.lock().map(|c|if c.locked{"Travar / destravar (travado)"}else{"Travar / destravar (destravado)"}).unwrap_or("Travar / destravar");let locked=MenuItem::with_id(app,"locked",label,true,None::<&str>)?;let top=MenuItem::with_id(app,"top","Alternar sempre no topo",true,None::<&str>)?;let login=MenuItem::with_id(app,"login","Entrar / mostrar janela de login",true,None::<&str>)?;let quit=MenuItem::with_id(app,"quit","Sair",true,None::<&str>)?;let menu=Menu::with_items(app,&[&toggle,&reload,&settings,&sep,&locked,&top,&login,&quit])?;let mut b=TrayIconBuilder::new().menu(&menu).tooltip("Widget Website — Calendário Econômico");if let Some(i)=app.default_window_icon().cloned(){b=b.icon(i)}b.on_menu_event(|app,e|match e.id().as_ref(){"show-hide"=>commands::toggle_main_visibility(app.clone()),"reload"=>commands::reload_site(app.clone()),"settings"=>commands::show_settings(app),"locked"=>commands::toggle_locked(app),"top"=>commands::toggle_topmost(app),"login"=>commands::show_login(app),"quit"=>commands::quit_app(app.clone()),_=>{}}).on_tray_icon_event(|tray,e|{if let TrayIconEvent::DoubleClick{button:MouseButton::Left,..}=e{commands::toggle_main_visibility(tray.app_handle().clone())}}).build(app)?;Ok(())}